contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint value) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(value > address(c).balance, "withdraw must exceed c balance to revert");
        uint before = address(this).balance;
        bool reverted;
        c.withdraw(value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = false;
        } else {
            reverted = true;
        }
        assert(reverted || address(this).balance == before);
    }

    receive() external payable {}
}

